export const TRAITS={size:{name:'Tamaño',min:.72,max:1.28},length:{name:'Longitud del cuerpo',min:.76,max:1.28},width:{name:'Anchura',min:.75,max:1.3},legs:{name:'Longitud de extremidades',min:.78,max:1.24},neck:{name:'Cuello',min:.7,max:1.3},tail:{name:'Cola',min:.65,max:1.4},speed:{name:'Agilidad',min:.75,max:1.25},metabolism:{name:'Metabolismo',min:.78,max:1.22},fertility:{name:'Fertilidad',min:.8,max:1.2},longevity:{name:'Longevidad',min:.85,max:1.18},hue:{name:'Pigmento',min:-.13,max:.13},pattern:{name:'Patrón',min:0,max:1},cognition:{name:'Capacidad cognitiva',min:.15,max:1.65},plasticity:{name:'Aprendizaje',min:.15,max:1.6},dexterity:{name:'Manipulación',min:.18,max:1.5},sociality:{name:'Sociabilidad',min:0,max:1.5},curiosity:{name:'Exploración',min:.1,max:1.5},assertion:{name:'Competencia',min:0,max:1.4}};
export function hash(x){x=Math.imul(x^(x>>>16),0x45d9f3b);x=Math.imul(x^(x>>>16),0x45d9f3b);return (x^(x>>>16))>>>0;}
export function seedRandom(seed){let x=seed>>>0||738159;return()=>{x^=x<<13;x^=x>>>17;x^=x<<5;return(x>>>0)/4294967296;};}
const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
export function genome(seed,mother=null,father=null){const rand=seedRandom(seed),dna={seed:seed>>>0,revision:0,alleles:{},traits:{},mutations:[]};for(const [key,t] of Object.entries(TRAITS)){let a,b;if(mother&&father){a=mother.alleles[key][rand()<.5?0:1];b=father.alleles[key][rand()<.5?0:1];if(rand()<.08){const index=rand()<.5?0:1,delta=(rand()-.5)*(t.max-t.min)*.22;if(index===0)a=clamp(a+delta,t.min,t.max);else b=clamp(b+delta,t.min,t.max);dna.mutations.push({trait:key,delta,origin:'Espontánea',allele:index});}}else{a=t.min+rand()*(t.max-t.min);b=t.min+rand()*(t.max-t.min);}dna.alleles[key]=[a,b];dna.traits[key]=(a+b)*.5;}return dna;}
export function mutateGenome(dna,rand){const keys=Object.keys(TRAITS),key=keys[Math.floor(rand()*keys.length)],t=TRAITS[key],i=rand()<.5?0:1,old=dna.alleles[key][i];let value=clamp(old+(rand()<.5?-1:1)*(t.max-t.min)*.22,t.min,t.max);if(value===old)value=clamp(old+(value===t.min?1:-1)*(t.max-t.min)*.22,t.min,t.max);dna.alleles[key][i]=value;dna.traits[key]=(dna.alleles[key][0]+dna.alleles[key][1])*.5;dna.revision++;dna.mutations.push({trait:key,delta:value-old,origin:'Intervención',allele:i});dna.mutations=dna.mutations.slice(-24);return TRAITS[key].name;}
export function patternName(dna){const p=dna.traits.pattern;return p<.33?'Moteado':p<.66?'Bandas':'Dorso contrastado';}

export function completeGenome(dna){const fresh=genome(dna.seed);for(const key of Object.keys(TRAITS))if(!dna.alleles[key]){dna.alleles[key]=fresh.alleles[key];dna.traits[key]=fresh.traits[key];}return dna;}
